def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def find_path(current, path, visited):
        if current == goal:
            return path

        row, col = current
        visited.add(current)

        neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]

        for next_row, next_col in neighbors:
            if is_valid(next_row, next_col) and (next_row, next_col) not in visited:
                result = find_path((next_row, next_col), path + [(next_row, next_col)], visited.copy())
                if result:
                    return result

        return None

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    if start == goal and is_valid(start[0], start[1]):
        return [start]

    path = find_path(start, [start], set())

    if path:
        return path
    else:
        return []
