def solve(grid, start, goal):
    if not grid:
        return []
    rows = len(grid)
    cols = len(grid[0])
    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []
    if start == goal:
        return [start]

    def get_neighbors(row, col):
        neighbors = []
        if row > 0 and grid[row - 1][col] == '.':
            neighbors.append((row - 1, col))
        if row < rows - 1 and grid[row + 1][col] == '.':
            neighbors.append((row + 1, col))
        if col > 0 and grid[row][col - 1] == '.':
            neighbors.append((row, col - 1))
        if col < cols - 1 and grid[row][col + 1] == '.':
            neighbors.append((row, col + 1))
        return neighbors

    def find_path(current, path, visited):
        if current == goal:
            return path + [current]

        neighbors = get_neighbors(current[0], current[1])
        for neighbor in neighbors:
            if neighbor not in visited:
                new_visited = visited.copy()
                new_visited.add(neighbor)
                result = find_path(neighbor, path + [current], new_visited)
                if result:
                    return result
        return None

    visited = {start}
    path = find_path(start, [], visited)
    return path if path else []
